const SOURCE = 'https://www.mutah.edu.jo/ar/enterprise/Home.aspx';
const HERO = 'data:image/jpeg;base64,';
const dateLabel = (value: string) => value ? new Date(value + 'T12:00:00').toLocaleDateString('ar-JO', {year:'numeric',month:'long',day:'numeric'}) : 'غير مؤرخ';

function Photos({images, title, single = false}: any) {
  if (!images?.length) return null;
  return <div className={single ? 'space-y-6' : 'grid grid-cols-1 sm:grid-cols-2 gap-6'}>
    {images.map((src: string, index: number) => <figure key={src} className="min-w-0">
      <a href={src} target="_blank" rel="noopener noreferrer" aria-label={`${title}، صورة ${index + 1}، فتح بالحجم الكامل`}>
        <img src={src} loading="lazy" alt={`${title}، صورة ${index + 1}`} className="w-full rounded-lg bg-slate-100" style={{objectFit:'contain',maxHeight:single ? 'none' : '420px'}} />
      </a>
      <figcaption className="text-xs text-slate-500 mt-2">{title} · {index + 1}</figcaption>
    </figure>)}
  </div>;
}
function Documents({docs}: any) {
  if (!docs?.length) return null;
  return <section className="mt-8"><h3 className="text-xl font-bold mb-4">الملفات والمرفقات</h3>
    <div className="divide-y divide-slate-200">{docs.map(([url,name]:string[]) => <a key={url} href={url} target="_blank" rel="noopener noreferrer" className="flex gap-3 items-center py-4 text-[#0f3057] underline underline-offset-4 break-words">
      <FileText size={20} className="shrink-0"/><span>{name.trim().replace(/\u200b/g,'') || decodeURIComponent(url.split('/').pop() || 'فتح المرفق')}</span>
    </a>)}</div>
  </section>;
}
function Source({url = SOURCE}: any) {
  return <p className="mt-10 pt-5 border-t border-slate-200 text-xs text-slate-500 leading-7">المصدر: <a className="underline text-[#0f3057]" href={url} target="_blank" rel="noopener noreferrer">الموقع الرسمي لمركز الريادة والابتكار، جامعة مؤتة</a> · مراجعة المعلومات: 12 سبتمبر 2026</p>;
}
function Content({page, tab}:any) {
  return <article className="bg-white rounded-xl p-5 md:p-9 text-[#0f3057]">
    <h2 className="text-2xl font-bold mb-6">{page.title}</h2>
    <div className="space-y-5 max-w-4xl text-slate-700 leading-9">{page.paragraphs.map((text:string,i:number)=><p key={i}>{text}</p>)}</div>
    {page.sections.map((section:any,i:number)=><section key={i} className="mt-8 max-w-4xl"><h3 className="text-xl font-bold mb-4">{section.title}</h3>
      {section.paragraphs?.map((text:string,j:number)=><p key={j} className="leading-9 text-slate-700">{text}</p>)}
      {section.items && <ul className="list-disc pr-6 space-y-3 text-slate-700 leading-8">{section.items.map((text:string,j:number)=><li key={j}>{text}</li>)}</ul>}
    </section>)}
    {page.rows.length > 0 && <div className="overflow-x-auto mt-7"><table className="w-full text-right text-sm leading-7">
      <caption className="sr-only">{page.title}</caption>
      <thead><tr className="bg-[#0f3057] text-white">{page.columns.map((column:string)=><th scope="col" key={column} className="p-4">{column}</th>)}</tr></thead>
      <tbody>{page.rows.map((row:string[],i:number)=><tr key={i} className="border-b border-slate-200 even:bg-slate-50">{row.map((value:string,j:number)=><td key={j} className="p-4">{value.includes('@')?<a href={'mailto:'+value} className="underline" dir="ltr">{value}</a>:value || 'غير منشور'}</td>)}</tr>)}</tbody>
    </table></div>}
    {tab === 'contact' && <div className="mt-6 space-y-4 leading-8">
      <p>الهاتف: <a className="underline" href="tel:+96232372380" dir="ltr">+962 3 2372380</a> · الفرعي <strong>3711</strong></p>
      <p>البريد: <a className="underline" href="mailto:ec@mutah.edu.jo" dir="ltr">ec@mutah.edu.jo</a></p>
      <div className="flex flex-wrap gap-5">{DATA.social.map((item:any)=><a className="underline" key={item.url} href={item.url} target="_blank" rel="noopener noreferrer">{item.label}</a>)}</div>
    </div>}
    {tab==='forms-project-support' && <p className="mt-6"><a className="underline" href="#/innovation-center/forms-download">الانتقال إلى نموذج طلب المشروع</a></p>}
    <Documents docs={page.docs}/>
    <div className="mt-8"><Photos images={page.images} title={page.title} single={['about-org-chart','expo-staff','about-director'].includes(tab)}/></div>
    <Source url={page.source}/>
  </article>;
}
function Archive({category, home = false}:any) {
  const [query,setQuery] = useState('');
  const [year,setYear] = useState('all');
  const [limit,setLimit] = useState(12);
  const location=useLocation();
  const articleId = new URLSearchParams(location.search).get('article');
  const entries=DATA.articles.filter((a:any)=>a.category===category);
  const article = !home && entries.find((a:any)=>a.id===articleId);
  if(article) return <article className="bg-white rounded-xl p-5 md:p-9">
    <a className="inline-block underline text-[#0f3057] mb-6" href={`#/innovation-center/${category}`}>العودة إلى {category==='news'?'الأخبار':'الفعاليات'}</a>
    <p className="text-sm text-slate-500 mb-3">{dateLabel(article.date)}</p>
    <h2 className="text-2xl md:text-3xl font-bold text-[#0f3057] leading-relaxed mb-6">{article.title}</h2>
    <p className="text-xs text-slate-500 mb-3">ملخص الخبر · المادة مؤرخة بحسب الأرشيف الرسمي</p>
    {article.paragraphs.map((text:string,i:number)=><p key={i} className="text-slate-700 leading-9 mb-6 max-w-4xl">{text}</p>)}
    <a href={article.source} target="_blank" rel="noopener noreferrer" className="inline-block underline text-[#0f3057] mb-8">قراءة النص الأصلي كاملًا</a>
    <Photos images={article.images} title={article.title}/><Documents docs={article.docs}/><Source url={article.source}/>
  </article>;
  const filtered=entries.filter((a:any)=>(year==='all'||a.date?.startsWith(year))&&(!query||a.title.includes(query)||a.paragraphs.join(' ').includes(query)));
  const shown=home?entries.slice(0,4):filtered.slice(0,limit);
  return <section className={home?'mt-12':'bg-white rounded-xl p-5 md:p-9'}>
    <div className="flex flex-wrap items-center justify-between gap-4 mb-6"><h2 className="text-2xl font-bold text-[#0f3057]">{category==='news'?'أخبار المركز':'الفعاليات والإعلانات'}</h2>
      {home?<a href={`#/innovation-center/${category}`} className="underline text-[#0f3057]">عرض الأرشيف</a>:<span className="text-sm text-slate-500">{filtered.length} مادة</span>}
    </div>
    {!home && <div className="flex flex-wrap gap-4 mb-6">
      <label className="flex-1 min-w-[180px] text-sm text-[#0f3057]">البحث في الأرشيف<input value={query} onChange={e=>{setQuery(e.target.value);setLimit(12)}} className="block w-full border border-slate-300 rounded-lg p-3 mt-2" placeholder="اكتب اسم الخبر أو كلمة مفتاحية"/></label>
      <label className="text-sm text-[#0f3057]">السنة<select value={year} onChange={e=>{setYear(e.target.value);setLimit(12)}} className="block border border-slate-300 rounded-lg p-3 mt-2"><option value="all">كل السنوات</option>{[...new Set(entries.map((a:any)=>a.date?.slice(0,4)).filter(Boolean))].map((y:any)=><option key={y} value={y}>{y}</option>)}</select></label>
    </div>}
    <div className="divide-y divide-slate-200">{shown.map((item:any)=><a key={item.id} href={`#/innovation-center/${category}?article=${item.id}`} className="flex flex-col sm:flex-row gap-5 py-6 group">
      {item.images[0]&&<img src={item.images[0]} alt="" loading="lazy" className="w-full sm:w-40 h-36 sm:h-28 object-cover rounded-lg bg-slate-100 shrink-0"/>}
      <div><p className="text-xs text-slate-500 mb-2">{dateLabel(item.date)}</p><h3 className="text-lg font-bold text-[#0f3057] leading-8 group-hover:underline">{item.title}</h3><p className="text-sm text-slate-600 leading-7 mt-2 line-clamp-2">{item.paragraphs[0]}</p><span className="text-sm underline text-[#0f3057] mt-3 inline-block">عرض التفاصيل والصور</span></div>
    </a>)}</div>
    {!shown.length&&<p className="py-10 text-slate-600">لا توجد نتائج مطابقة. جرّب كلمة أخرى أو اختر كل السنوات.</p>}
    {!home&&filtered.length>limit&&<button className="mt-6 px-6 py-3 rounded-lg bg-[#0f3057] text-white" onClick={()=>setLimit(limit+12)}>عرض المزيد ({filtered.length-limit})</button>}
    {!home&&<Source url={DATA.pages[category].source}/>}
  </section>;
}
function InnovationContent({activeItem}:any) {
  if(activeItem==='home')return <>
    <section className="bg-white rounded-xl p-6 md:p-9 text-[#0f3057]"><p className="text-sm text-slate-500 mb-3">الريادة في جامعة مؤتة</p><h2 className="text-2xl font-bold mb-5">من الفكرة إلى المشروع</h2>
      <p className="text-slate-700 leading-9 max-w-4xl">تأسس المركز بقرار مجلس التعليم العالي في 28 فبراير 2018، ويعمل على تنمية قدرات الطلبة والمجتمع المحلي، واحتضان الأفكار ودعم أصحاب المشاريع بالتدريب والاستشارات والشراكات.</p>
      <div className="flex flex-wrap gap-3 mt-6">{[['services','خدمات المركز'],['forms-project-support','احتضان مشروع'],['forms-download','نموذج الطلب'],['contact','تواصل معنا']].map(([id,name])=><a key={id} href={`#/innovation-center/${id}`} className="border border-[#0f3057] text-[#0f3057] px-5 py-3 rounded-lg hover:bg-slate-50">{name}</a>)}</div>
    </section><Archive category="news" home/><Archive category="events" home/><Source/>
  </>;
  if(activeItem==='news'||activeItem==='events')return <Archive category={activeItem}/>;
  const page=DATA.pages[activeItem];
  if(!page)return <p>اختر صفحة من قائمة المركز. <a href="#/innovation-center" className="underline">الرئيسية</a></p>;
  return <Content page={page} tab={activeItem}/>;
}
export function InnovationCenter() {
  return <CenterLayout centerName="مركز الريادة والابتكار" links={LINKS} heroDescription="تطوير المهارات الريادية، واحتضان الأفكار المبتكرة، ودعم مشاريع الجامعة والمجتمع المحلي." heroImage={HERO} heroVariant="photo">
    {(activeItem)=><InnovationContent key={activeItem} activeItem={activeItem}/>}
  </CenterLayout>;
}
